// Runs peak detection and deconvolution of the old MetaboliteDetector 3.3 (Linux) on .cdf files
// without its GUI and prints the results as text. See make-reference.sh for how it is used.
//
// Loaded with LD_PRELOAD into the old binary: it replaces main() and calls the binary's own
// functions (CdfImporter -> GCMSDiskScan -> GCMSAnalyzer) in the order the GUI uses
// (MainWindow::start, ComponentDetector::detectComponents). Function addresses come from
// syms.inc, generated by make-reference.sh from `nm`. Settings are the static defaults
// compiled into the binary (GCMSSettings::AN_*); no config file is read. With MD_MATCHED="WIDTH THRESHOLD"
// the analyzer gets a MatchedPeakDetector(WIDTH, THRESHOLD) like the "Matched Filtering" method of the
// Calibration Setter window (CalibrationSetter::threadFinished); otherwise a DefaultPeakDetector.
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <new>
#include <string>
#include <vector>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

using Self = const void*;
float ion(Self p) { return fn<float (*)(Self)>(PE_ION)(p); }
unsigned first(Self p) { return fn<unsigned (*)(Self)>(PE_FIRST)(p); }
unsigned last(Self p) { return fn<unsigned (*)(Self)>(PE_LAST)(p); }
unsigned apex(Self p) { return fn<unsigned (*)(Self)>(PE_MAX)(p); }
double interp(Self p) { return fn<double (*)(Self)>(PE_INTERP)(p); }
double integral(Self p) { return fn<double (*)(Self)>(PE_INTEGRAL)(p); }
double quality(Self p) { return fn<double (*)(Self)>(PE_QUALITY)(p); }
double sharpness(Self p) { return fn<double (*)(Self)>(PE_SHARPNESS)(p); }
double sn(Self p) { return fn<double (*)(Self)>(PE_SN)(p); }
double model(Self p) { return fn<double (*)(Self)>(PE_MODEL)(p); }

void peak_fields(FILE* out, Self p) {
    std::fprintf(out, "%g\t%u\t%u\t%u\t%.9g\t%.9g\t%.9g\t%.9g\t%.9g\t%.9g", ion(p), first(p), apex(p),
                 last(p), interp(p), sn(p), quality(p), sharpness(p), integral(p), model(p));
}

// std::list node: next, prev, value (libstdc++ ABI, same compiler family as the old binary).
struct ListNode { ListNode* next; ListNode* prev; };

void run(FILE* out, const char* cdf, const char* work) {
    std::string name = std::strrchr(cdf, '/') ? std::strrchr(cdf, '/') + 1 : cdf;
    std::string stem = std::string(work) + "/" + name.substr(0, name.rfind('.'));

    alignas(16) static char importer[1 << 16];
    fn<void (*)(void*, const char*)>(CDF_IMPORTER_CTOR)(importer, cdf);
    fn<void (*)(void*, const char*)>(CDF_IMPORT_DATA)(importer, stem.c_str());
    fn<void (*)(void*)>(CDF_IMPORTER_DTOR)(importer);

    void* scan = ::operator new(0x390);  // size from MainWindow / CompoundDetector::detect
    fn<void (*)(void*, const char*, bool, bool, void*)>(DISK_SCAN_CTOR)(scan, stem.c_str(), false, false, nullptr);
    void* detector = ::operator new(0x20);
    unsigned long width;
    int threshold;
    if (const char* m = std::getenv("MD_MATCHED"); m && std::sscanf(m, "%lu %d", &width, &threshold) == 2)
        fn<void (*)(void*, unsigned long, int)>(MATCHED_DETECTOR_CTOR)(detector, width, threshold);
    else
        fn<void (*)(void*)>(DEFAULT_DETECTOR_CTOR)(detector);
    auto* an = static_cast<char*>(::operator new(0xb0));
    fn<void (*)(void*, void*, void*)>(ANALYZER_CTOR)(an, scan, detector);

    unsigned scans = static_cast<unsigned>(fn<unsigned long (*)(Self)>(DISK_SCAN_COUNT)(scan));
    double nf = *reinterpret_cast<double*>(an + 0x70);
    std::fprintf(out, "run\t%s\tscans\t%u\tnoise_factor\t%.9g\trt0\t%.9g\trt1\t%.9g\n", name.c_str(), scans, nf,
                 fn<double (*)(Self, unsigned)>(DISK_SCAN_RT)(scan, 0),
                 fn<double (*)(Self, unsigned)>(DISK_SCAN_RT)(scan, 1));

    // ComponentDetector::detectComponents: detectAllPeaks(true, 10.0f, 0.05f), deconvoluteChromatogram().
    const float scan_dist = 10.0f, ion_dist = 0.05f;
    if (!fn<bool (*)(void*, bool, const float&, const float&)>(DETECT_ALL_PEAKS)(an, true, scan_dist, ion_dist)) {
        std::fprintf(stderr, "%s: detectAllPeaks failed\n", cdf);
        return;
    }
    // GCMSAnalyzer::peaks: std::list<Peak<int,float>> at +0x10; Peak starts with its PeakEssential.
    auto* head = reinterpret_cast<ListNode*>(an + 0x10);
    for (ListNode* n = head->next; n != head; n = n->next) {
        std::fputs("peak\t", out);
        peak_fields(out, n + 1);
        std::fputc('\n', out);
    }

    fn<void (*)(void*)>(DECONVOLUTE)(an);
    // GCMSAnalyzer::compounds: std::vector<Compound<int,float>*> at +0x58; Compound starts with its Spectrum.
    auto* comps = reinterpret_cast<std::vector<void*>*>(an + 0x58);
    for (void* c : *comps) {
        auto* masses = fn<const std::vector<float>* (*)(Self)>(SPEC_MASSES)(c);
        auto* values = fn<const std::vector<int>* (*)(Self)>(SPEC_VALUES)(c);
        std::fprintf(out, "component\t%u\t%.9g\t%zu\n", fn<unsigned (*)(Self)>(SPEC_SCAN)(c),
                     fn<double (*)(Self)>(SPEC_RT)(c), masses->size());
        for (size_t i = 0; i < masses->size(); i++)
            std::fprintf(out, "ion\t%g\t%d\n", (*masses)[i], (*values)[i]);
        alignas(8) char buf[sizeof(std::vector<Self>)];
        fn<void (*)(void*, Self)>(COMPOUND_PEAKS)(buf, c);
        auto* peaks = reinterpret_cast<std::vector<Self>*>(buf);
        for (Self p : *peaks) {
            std::fputs("cpeak\t", out);
            peak_fields(out, p);
            std::fputc('\n', out);
        }
        peaks->~vector();
    }
    // MD_RESULTS: also save the components as the old GUI does ("Save compounds", .cmp).
    if (const char* dir = std::getenv("MD_RESULTS")) {
        std::string cmp = std::string(dir) + "/" + name.substr(0, name.rfind('.')) + ".cmp";
        fn<void (*)(const std::vector<void*>&, const char*)>(COMPOUND_TO_DISK)(*comps, cmp.c_str());
    }
    std::fflush(out);
    // Objects are leaked on purpose: the process ends after the last file.
}

// RICalculator: vtable, std::map rt2ri, drt, std::string source; the buffer is larger than that.
struct Calib { alignas(16) char obj[512]; };

void calib_new(Calib& c, const char* source) {
    fn<void (*)(void*, const std::string&)>(RI_CTOR)(c.obj, std::string(source));
}

void calib_save(Calib& c, const std::string& stem) {
    fn<void (*)(void*, const char*)>(RI_TO_DISK)(c.obj, (stem + ".calib").c_str());
    std::ofstream bin(stem + ".calib.bin", std::ios::binary);
    fn<void (*)(const void*, std::ostream&)>(RI_TO_STREAM)(c.obj, bin);
}

// A calibration with known values, written in both forms (text .calib and binary toStream).
void write_calibration(const char* dir) {
    Calib c;
    calib_new(c, "harness");
    const double pairs[][2] = {{300000, 1000}, {612345.678901, 1500.5}, {901234.5, 2000.25}, {1.5e6, 3000}};
    for (auto& p : pairs) fn<void (*)(void*, const double&, const double&)>(RI_ADD_PAIR)(c.obj, p[0], p[1]);
    calib_save(c, std::string(dir) + "/harness");
}

// Reads files with the old code and writes them again: IN.cmp -> OUT.cmp, IN.calib -> OUT.calib,
// IN.calib.bin -> OUT.calib.bin (by suffix). Checks that the old program accepts our writer.
int reread(int argc, char** argv) {
    for (int i = 2; i + 1 < argc; i += 2) {
        std::string in = argv[i], out = argv[i + 1];
        auto ends = [](const std::string& s, const char* x) {
            return s.size() >= std::strlen(x) && s.compare(s.size() - std::strlen(x), std::string::npos, x) == 0;
        };
        if (ends(in, ".cmp")) {
            std::vector<void*> comps;
            fn<void (*)(std::vector<void*>*, const char*)>(COMPOUND_FROM_DISK)(&comps, in.c_str());
            fn<void (*)(const std::vector<void*>&, const char*)>(COMPOUND_TO_DISK)(comps, out.c_str());
        } else {
            Calib c;
            calib_new(c, "");
            if (ends(in, ".bin")) {
                std::ifstream bin(in, std::ios::binary);
                fn<void (*)(void*, std::istream&)>(RI_FROM_STREAM)(c.obj, bin);
                std::ofstream o(out, std::ios::binary);
                fn<void (*)(const void*, std::ostream&)>(RI_TO_STREAM)(c.obj, o);
            } else {
                fn<void (*)(void*, const char*)>(RI_FROM_DISK)(c.obj, in.c_str());
                fn<void (*)(void*, const char*)>(RI_TO_DISK)(c.obj, out.c_str());
            }
        }
    }
    return 0;
}

// usage: LD_PRELOAD=old_md_dump.so metabolitedetector_app WORK_DIR OUT.tsv RUN.cdf...
//        LD_PRELOAD=old_md_dump.so metabolitedetector_app --reread IN OUT [IN OUT]...
int dump_main(int argc, char** argv, char**) {
    if (argc >= 2 && std::strcmp(argv[1], "--reread") == 0) return reread(argc, argv);
    if (argc < 4) {
        std::fprintf(stderr, "usage: %s WORK_DIR OUT.tsv RUN.cdf...\n", argv[0]);
        return 2;
    }
    FILE* out = std::fopen(argv[2], "w");
    if (!out) { std::perror(argv[2]); return 1; }
    for (int i = 3; i < argc; i++) run(out, argv[i], argv[1]);
    if (const char* dir = std::getenv("MD_RESULTS")) write_calibration(dir);
    return std::fclose(out) == 0 ? 0 : 1;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(dump_main, argc, argv, init, fini, rtld_fini, stack_end);
}
